\version "2.27.2"
% automatically converted by musicxml2ly from 45e-Repeats-Combination.xml
\pointAndClickOff

\header {
  texidoc = "A series of repeat elements.

    The first repeat starts implicitly at the beginning, with the first
    alternative starting and ending at bar 2, and the second ending at bar 3.
    All four <ending> elements have ‘number=\"\"’ as an attribute. The next
    repeat starts and ends at bar 5. Another repeat starts at bar 6 (causing a
    back-to-back bar line between bars 5 and 6), with the first alternative
    starting and ending at bar 7. Its second alternative (starting and ending at
    bar 8) is the start of a repeat at the same time (causing another
    back-to-back bar line between bars 7 and 8), ending after bar 9."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    doubleRepeatBarType = ":|.|:"
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \repeat volta 2 {
    \clef "treble" \time 4/4 \key c \major R1 | % 1
    \alternative {
      \volta 1 {
        R1 | % 2
      }
      \volta 2 {
        R1 | % 3
      }
    }
  }
  R1 | % 4
  \repeat volta 2 {
    R1 | % 5
  }
  \repeat volta 2 {
    R1 | % 6
    \alternative {
      \volta 1 {
        R1 | % 7
      }
      \volta 2 {
        \repeat volta 2 {
          R1 | % 8
          R1 | % 9

          \barNumberCheck #10
        }
      }
    }
  }
  R1 \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
